export const Hgroup = ({ title, sub, long = false }) => (
  <div className={`hgroup ${long ? "hgroup--long" : ""}`}>
    <h1>{title}</h1>
    {sub && <p className="sub">{sub}</p>}
  </div>
);

export const Field = ({
  id,
  label,
  hint,
  type = "text",
  value,
  optional = false,
  password = false,
  autocomplete,
  inputmode,
  onChange,
}) => {
  const [showPassword, setShowPassword] = useState(false);

  const togglePassword = () => {
    setShowPassword((prev) => !prev);
  };

  return (
    <div className="field">
      <label className="field__label" htmlFor={id}>
        {label}
        {optional && <em> (Optional)</em>}
      </label>

      <div className="field__box">
        <input
          id={id}
          name={id}
          type={
            password
              ? showPassword
                ? "text"
                : "password"
              : type
          }
          placeholder={hint || ""}
          value={value || ""}
          autoComplete={autocomplete}
          inputMode={inputmode}
          onChange={onChange}
        />

        {password && (
          <button
            className="field__toggle"
            type="button"
            aria-label={
              showPassword
                ? "Hide password"
                : "Show password"
            }
            onClick={togglePassword}
          >
            {showPassword ? ICON.eye : ICON.hidden}
          </button>
        )}
      </div>
    </div>
  );
};



export const Btn = ({
  label,
  loading = false,
  variant = "primary",
  go,
  act,
  onClick
}) => {
  if (loading) {
    return (
      <button
        className="btn btn--loading"
        type="button"
        aria-busy="true"
      >
        {ICON.loader}
        <span>{label}</span>
      </button>
    );
  }

  return (
    <button
      className={`btn ${
        variant === "ghost" ? "btn--ghost" : "btn--primary"
      }`}
      type="button"
      data-go={go}
      data-act={act}
      onClick={onClick}
    >
      {label}
    </button>
  );
};

export const Footnote = ({ text, linkLabel, to, onClick }) => (
  <p className="footnote">
    {text}
    <a
      href="#"
      data-go={to}
      onClick={onClick}
    >
      {linkLabel}
    </a>
  </p>
);

export const Stepper = ({ step }) => (
  <div className="stepper" data-step={step}>
    <div
      className="stepper__step"
      data-state={step > 1 ? "done" : "active"}
    >
      <span className="stepper__dot">
        {step > 1 ? ICON.tick : "1"}
      </span>
      <span className="stepper__label">Details</span>
    </div>

    <span className="stepper__rule" />

    <div
      className="stepper__step"
      data-state={step === 2 ? "active" : "todo"}
    >
      <span className="stepper__dot">2</span>
      <span className="stepper__label">Password</span>
    </div>
  </div>
);

